// Revenue Tracker — Aggregates all revenue sources
const now = new Date();
const today = now.toISOString().split('T')[0];

// Simulated data structure — replace with real API calls
const revenue = {
  date: today,
  timestamp: now.toISOString(),
  sources: {
    gumroad: { name: 'Gumroad Products', amount: 0, currency: 'EUR' },
    stripe: { name: 'Stripe Payments', amount: 0, currency: 'EUR' },
    paypal: { name: 'PayPal (Direct)', amount: 0, currency: 'EUR' },
    fiverr: { name: 'Fiverr Gigs', amount: 0, currency: 'EUR' },
    consulting: { name: 'Direct Consulting', amount: 0, currency: 'EUR' }
  },
  total: 0,
  target_daily: 333, // €10K/month target
  target_monthly: 10000,
  days_in_month: new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate(),
  day_of_month: now.getDate()
};

revenue.total = Object.values(revenue.sources).reduce((sum, s) => sum + s.amount, 0);
revenue.run_rate = (revenue.total / revenue.day_of_month) * revenue.days_in_month;
revenue.on_track = revenue.run_rate >= revenue.target_monthly;
revenue.gap = revenue.target_monthly - revenue.run_rate;

return [{ json: revenue }];

